import{_ as i,o as a,c as s,a2 as n}from"./chunks/framework.D9DTPhg1.js";const m=JSON.parse('{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"reference/configuration.md","filePath":"packages/bundle/docs/reference/configuration.md"}'),t={name:"reference/configuration.md"};function r(o,e,d,h,l,p){return a(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h1><p>Every option of <code>config/packages/prism.yaml</code>. An unknown option is refused when the container compiles, with a message that names it. This page is checked against the configuration tree of the bundle.</p><p>The complete form, with the default values:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">prism</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    default_entity_manager</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">~</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">             # the first declared entity manager</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    connections</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        default</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">            url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;%env(resolve:DATABASE_URL)%&#39;</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    entity_managers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        default</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">            connection</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">~</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                 # the connection with the same name, or the only one</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">            entity_dirs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;%kernel.project_dir%/src/Entity&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">            batch_size</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">100</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">            migrations</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">                dir</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">~</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                    # migrations/, or migrations/&lt;Name&gt; for another entity manager</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">                namespace</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">~</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # App\\Migrations, or App\\Migrations\\&lt;Name&gt;</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    connection_idle_ttl</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">60</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    tenancy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">integer</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        guard</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">~</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                          # exception in debug, log otherwise</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        resolver</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">~</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                       # one of header, subdomain, user</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        loader</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">~</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    embeddings</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        scheduler</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">auto</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                   # messenger if a message bus exists, deferred otherwise</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        batch_size</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">64</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        providers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {}                     </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># &lt;name&gt;: { service: … } or { openai: { … } }</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    metamodel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        dir</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;%kernel.cache_dir%/prism/metamodel&#39;</span></span></code></pre></div><h2 id="short-form" tabindex="-1">Short form <a class="header-anchor" href="#short-form" aria-label="Permalink to &quot;Short form&quot;">​</a></h2><p>With one database and one entity manager, <code>url</code>, <code>entity_dirs</code> and <code>migrations</code> can be written at the root. They declare the <code>default</code> connection and entity manager, and cannot be mixed with <code>connections</code> and <code>entity_managers</code>.</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">prism</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;%env(resolve:DATABASE_URL)%&#39;</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    entity_dirs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;%kernel.project_dir%/src/Entity&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    migrations</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        dir</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;%kernel.project_dir%/migrations&#39;</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        namespace</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;App\\Migrations&#39;</span></span></code></pre></div><h3 id="prism-url" tabindex="-1"><code>prism.url</code> <a class="header-anchor" href="#prism-url" aria-label="Permalink to &quot;`prism.url`&quot;">​</a></h3><p>The URL of the <code>default</code> connection. Without <code>url</code> and <code>connections</code>, Prism uses <code>%env(resolve:DATABASE_URL)%</code>, read on first use only.</p><h3 id="prism-entity-dirs" tabindex="-1"><code>prism.entity_dirs</code> <a class="header-anchor" href="#prism-entity-dirs" aria-label="Permalink to &quot;`prism.entity_dirs`&quot;">​</a></h3><p>The entity directories of the <code>default</code> entity manager.</p><h3 id="prism-migrations-dir" tabindex="-1"><code>prism.migrations.dir</code> <a class="header-anchor" href="#prism-migrations-dir" aria-label="Permalink to &quot;`prism.migrations.dir`&quot;">​</a></h3><p>The migrations directory of the <code>default</code> entity manager.</p><h3 id="prism-migrations-namespace" tabindex="-1"><code>prism.migrations.namespace</code> <a class="header-anchor" href="#prism-migrations-namespace" aria-label="Permalink to &quot;`prism.migrations.namespace`&quot;">​</a></h3><p>The namespace of its migrations.</p><h2 id="connections" tabindex="-1">Connections <a class="header-anchor" href="#connections" aria-label="Permalink to &quot;Connections&quot;">​</a></h2><h3 id="prism-connections-name-url" tabindex="-1"><code>prism.connections.&lt;name&gt;.url</code> <a class="header-anchor" href="#prism-connections-name-url" aria-label="Permalink to &quot;`prism.connections.&lt;name&gt;.url`&quot;">​</a></h3><p>The URL of a named connection, in Symfony&#39;s format, with <code>serverVersion</code>: <code>mysql://user:pass@host:3306/db?serverVersion=8.4</code>. Required.</p><h2 id="entity-managers" tabindex="-1">Entity managers <a class="header-anchor" href="#entity-managers" aria-label="Permalink to &quot;Entity managers&quot;">​</a></h2><h3 id="prism-default-entity-manager" tabindex="-1"><code>prism.default_entity_manager</code> <a class="header-anchor" href="#prism-default-entity-manager" aria-label="Permalink to &quot;`prism.default_entity_manager`&quot;">​</a></h3><p>The entity manager behind <code>EntityManagerInterface</code> and <code>bin/console db:*</code> without <code>--em</code>. Default: the first declared.</p><h3 id="prism-entity-managers-name-connection" tabindex="-1"><code>prism.entity_managers.&lt;name&gt;.connection</code> <a class="header-anchor" href="#prism-entity-managers-name-connection" aria-label="Permalink to &quot;`prism.entity_managers.&lt;name&gt;.connection`&quot;">​</a></h3><p>The connection of the entity manager. Default: the connection with the same name, or the only connection if there is one.</p><h3 id="prism-entity-managers-name-entity-dirs" tabindex="-1"><code>prism.entity_managers.&lt;name&gt;.entity_dirs</code> <a class="header-anchor" href="#prism-entity-managers-name-entity-dirs" aria-label="Permalink to &quot;`prism.entity_managers.&lt;name&gt;.entity_dirs`&quot;">​</a></h3><p>The directories of its entity classes, at least one. Default: <code>%kernel.project_dir%/src/Entity</code>.</p><h3 id="prism-entity-managers-name-batch-size" tabindex="-1"><code>prism.entity_managers.&lt;name&gt;.batch_size</code> <a class="header-anchor" href="#prism-entity-managers-name-batch-size" aria-label="Permalink to &quot;`prism.entity_managers.&lt;name&gt;.batch_size`&quot;">​</a></h3><p>The largest number of entities loaded by one <code>IN</code> query of <a href="/prism/guide/n-plus-one#batch-size">batch fetching</a>, at least 1. Default: <code>100</code>. A relation can set its own with <code>batchSize</code>.</p><h3 id="prism-entity-managers-name-migrations-dir" tabindex="-1"><code>prism.entity_managers.&lt;name&gt;.migrations.dir</code> <a class="header-anchor" href="#prism-entity-managers-name-migrations-dir" aria-label="Permalink to &quot;`prism.entity_managers.&lt;name&gt;.migrations.dir`&quot;">​</a></h3><p>Its migrations directory. Default: <code>%kernel.project_dir%/migrations</code> for the default entity manager, <code>migrations/&lt;Name&gt;</code> for the others.</p><h3 id="prism-entity-managers-name-migrations-namespace" tabindex="-1"><code>prism.entity_managers.&lt;name&gt;.migrations.namespace</code> <a class="header-anchor" href="#prism-entity-managers-name-migrations-namespace" aria-label="Permalink to &quot;`prism.entity_managers.&lt;name&gt;.migrations.namespace`&quot;">​</a></h3><p>The namespace of its migrations. Default: <code>App\\Migrations</code>, or <code>App\\Migrations\\&lt;Name&gt;</code>.</p><h2 id="worker-mode" tabindex="-1">Worker mode <a class="header-anchor" href="#worker-mode" aria-label="Permalink to &quot;Worker mode&quot;">​</a></h2><h3 id="prism-connection-idle-ttl" tabindex="-1"><code>prism.connection_idle_ttl</code> <a class="header-anchor" href="#prism-connection-idle-ttl" aria-label="Permalink to &quot;`prism.connection_idle_ttl`&quot;">​</a></h3><p>Under FrankenPHP or RoadRunner: after this many seconds without a query, the connection is checked at the start of the next request, and reconnected if it was lost. <code>0</code> checks it on every request. Default: <code>60</code>.</p><h2 id="multi-tenancy" tabindex="-1">Multi-tenancy <a class="header-anchor" href="#multi-tenancy" aria-label="Permalink to &quot;Multi-tenancy&quot;">​</a></h2><p>See <a href="/prism/guide/multi-tenancy#in-symfony">Multi-tenancy</a>.</p><h3 id="prism-tenancy-type" tabindex="-1"><code>prism.tenancy.type</code> <a class="header-anchor" href="#prism-tenancy-type" aria-label="Permalink to &quot;`prism.tenancy.type`&quot;">​</a></h3><p>The type of the <code>tenant_id</code> column of every <code>#[Tenanted]</code> entity: <code>integer</code>, <code>bigint</code> or <code>uuid</code>. Default: <code>integer</code>.</p><h3 id="prism-tenancy-guard" tabindex="-1"><code>prism.tenancy.guard</code> <a class="header-anchor" href="#prism-tenancy-guard" aria-label="Permalink to &quot;`prism.tenancy.guard`&quot;">​</a></h3><p>What the guard does with raw SQL on a tenanted table without a tenant condition: <code>exception</code>, or <code>log</code> (a critical log entry). Default: <code>exception</code> in debug, <code>log</code> otherwise.</p><h3 id="prism-tenancy-resolver-header" tabindex="-1"><code>prism.tenancy.resolver.header</code> <a class="header-anchor" href="#prism-tenancy-resolver-header" aria-label="Permalink to &quot;`prism.tenancy.resolver.header`&quot;">​</a></h3><p>Read the tenant from this request header, <code>X-Tenant-Id</code> for example. Before the firewall. <strong>Only behind a gateway that sets the header itself</strong>: otherwise, any client chooses its tenant.</p><h3 id="prism-tenancy-resolver-subdomain" tabindex="-1"><code>prism.tenancy.resolver.subdomain</code> <a class="header-anchor" href="#prism-tenancy-resolver-subdomain" aria-label="Permalink to &quot;`prism.tenancy.resolver.subdomain`&quot;">​</a></h3><p>Read the tenant from the subdomain under this domain: <code>acme</code> in <code>acme.example.com</code> under <code>example.com</code>. Before the firewall.</p><h3 id="prism-tenancy-resolver-user" tabindex="-1"><code>prism.tenancy.resolver.user</code> <a class="header-anchor" href="#prism-tenancy-resolver-user" aria-label="Permalink to &quot;`prism.tenancy.resolver.user`&quot;">​</a></h3><p><code>true</code>: the tenant of the logged-in user, which implements <code>TenantAwareUserInterface</code>. After the firewall; the user entity must not be tenanted.</p><p>Only one of <code>header</code>, <code>subdomain</code> and <code>user</code> can be set. Without any, the application sets the tenant on the <code>StackTenantContext</code> service.</p><h3 id="prism-tenancy-loader" tabindex="-1"><code>prism.tenancy.loader</code> <a class="header-anchor" href="#prism-tenancy-loader" aria-label="Permalink to &quot;`prism.tenancy.loader`&quot;">​</a></h3><p>The id of a <code>TenantLoader</code> service that turns the identifier read by the resolver (a header value, a subdomain) into the tenant identifier. Without it, the identifier read is the tenant, an integer for <code>integer</code> and <code>bigint</code>.</p><h2 id="embeddings" tabindex="-1">Embeddings <a class="header-anchor" href="#embeddings" aria-label="Permalink to &quot;Embeddings&quot;">​</a></h2><p>The providers and the computation of the <code>#[EmbeddedVector]</code> fields. See <a href="/prism/bundle/symfony#embeddings">Embeddings</a>.</p><h3 id="prism-embeddings-scheduler" tabindex="-1"><code>prism.embeddings.scheduler</code> <a class="header-anchor" href="#prism-embeddings-scheduler" aria-label="Permalink to &quot;`prism.embeddings.scheduler`&quot;">​</a></h3><p>What happens to the vectors a flush made stale, once its transaction is committed: <code>messenger</code> dispatches <code>ComputeEmbedding</code> messages, <code>synchronous</code> computes them at once, <code>deferred</code> leaves them to <code>db:embeddings:compute</code>. Default: <code>auto</code>, which is <code>messenger</code> when a message bus exists, <code>deferred</code> otherwise. <code>messenger</code> without a bus is refused.</p><h3 id="prism-embeddings-batch-size" tabindex="-1"><code>prism.embeddings.batch_size</code> <a class="header-anchor" href="#prism-embeddings-batch-size" aria-label="Permalink to &quot;`prism.embeddings.batch_size`&quot;">​</a></h3><p>The texts sent to a provider in one call, the ids in one <code>ComputeEmbedding</code> message, and the messages the handler processes together. Default: <code>64</code>.</p><h3 id="prism-embeddings-providers-name-service" tabindex="-1"><code>prism.embeddings.providers.&lt;name&gt;.service</code> <a class="header-anchor" href="#prism-embeddings-providers-name-service" aria-label="Permalink to &quot;`prism.embeddings.providers.&lt;name&gt;.service`&quot;">​</a></h3><p>The id of a service that implements <code>EmbeddingProvider</code>, registered under <code>&lt;name&gt;</code>: the name that <code>#[EmbeddedVector(model:)]</code> gives. A provider is either <code>service</code> or <code>openai</code>.</p><h3 id="prism-embeddings-providers-name-openai-base-url" tabindex="-1"><code>prism.embeddings.providers.&lt;name&gt;.openai.base_url</code> <a class="header-anchor" href="#prism-embeddings-providers-name-openai-base-url" aria-label="Permalink to &quot;`prism.embeddings.providers.&lt;name&gt;.openai.base_url`&quot;">​</a></h3><p>The base URL of an API in the OpenAI format, without <code>/embeddings</code>: <code>https://api.openai.com/v1</code>, <code>http://ollama:11434/v1</code>. Needs <code>prism-orm/embedding-openai</code> and <code>symfony/http-client</code>.</p><h3 id="prism-embeddings-providers-name-openai-model" tabindex="-1"><code>prism.embeddings.providers.&lt;name&gt;.openai.model</code> <a class="header-anchor" href="#prism-embeddings-providers-name-openai-model" aria-label="Permalink to &quot;`prism.embeddings.providers.&lt;name&gt;.openai.model`&quot;">​</a></h3><p>The model sent with each request, and stored with each vector it computes.</p><h3 id="prism-embeddings-providers-name-openai-dimensions" tabindex="-1"><code>prism.embeddings.providers.&lt;name&gt;.openai.dimensions</code> <a class="header-anchor" href="#prism-embeddings-providers-name-openai-dimensions" aria-label="Permalink to &quot;`prism.embeddings.providers.&lt;name&gt;.openai.dimensions`&quot;">​</a></h3><p>The dimension of its vectors. It must equal the <code>dimensions</code> of the column, checked at <code>cache:warmup</code>, and every response is checked against it.</p><h3 id="prism-embeddings-providers-name-openai-api-key" tabindex="-1"><code>prism.embeddings.providers.&lt;name&gt;.openai.api_key</code> <a class="header-anchor" href="#prism-embeddings-providers-name-openai-api-key" aria-label="Permalink to &quot;`prism.embeddings.providers.&lt;name&gt;.openai.api_key`&quot;">​</a></h3><p>The API key, sent as a bearer token. <code>~</code> for a local server. Use an environment variable: <code>&#39;%env(OPENAI_API_KEY)%&#39;</code>.</p><h3 id="prism-embeddings-providers-name-openai-send-dimensions" tabindex="-1"><code>prism.embeddings.providers.&lt;name&gt;.openai.send_dimensions</code> <a class="header-anchor" href="#prism-embeddings-providers-name-openai-send-dimensions" aria-label="Permalink to &quot;`prism.embeddings.providers.&lt;name&gt;.openai.send_dimensions`&quot;">​</a></h3><p><code>true</code> sends the dimension with each request, for the models that reduce it (<code>text-embedding-3-*</code>). Default: <code>false</code>.</p><h3 id="prism-embeddings-providers-name-openai-prefix" tabindex="-1"><code>prism.embeddings.providers.&lt;name&gt;.openai.prefix</code> <a class="header-anchor" href="#prism-embeddings-providers-name-openai-prefix" aria-label="Permalink to &quot;`prism.embeddings.providers.&lt;name&gt;.openai.prefix`&quot;">​</a></h3><p>Put before each text. Some models expect a prefix that tells documents from questions: <code>&#39;search_document: &#39;</code> and <code>&#39;search_query: &#39;</code> for <code>nomic-embed-text</code>, as two providers of the same model. Default: <code>&#39;&#39;</code>.</p><h2 id="metamodel" tabindex="-1">Metamodel <a class="header-anchor" href="#metamodel" aria-label="Permalink to &quot;Metamodel&quot;">​</a></h2><h3 id="prism-metamodel-dir" tabindex="-1"><code>prism.metamodel.dir</code> <a class="header-anchor" href="#prism-metamodel-dir" aria-label="Permalink to &quot;`prism.metamodel.dir`&quot;">​</a></h3><p>The directory of the generated <a href="/prism/guide/query-builder#the-metamodel">metamodel</a>; each entity manager generates into <code>&lt;dir&gt;/&lt;name&gt;</code>. Default: <code>%kernel.cache_dir%/prism/metamodel</code>.</p>',72)])])}const k=i(t,[["render",r]]);export{m as __pageData,k as default};
